function allTramos() {
  return RIVERS.flatMap((r) => r.tramos.map((t) => ({ ...t, rioId: r.id, rioNombre: r.nombre, rioColor: r.color })));
}

function tramoById(id) {
  return allTramos().find((t) => t.id === id);
}

function allWaterbodies() {
  return WATERBODIES;
}

function waterbodyById(id) {
  return WATERBODIES.find((w) => w.id === id);
}

function allInteractables() {
  return [...allTramos(), ...allWaterbodies()];
}

